### Core login implementation

```python
import os
import logging
from urllib.parse import urlparse, urljoin

from flask import Flask, render_template, redirect, url_for, flash, request, abort
from flask_sqlalchemy import SQLAlchemy
from flask_login import (
    LoginManager,
    UserMixin,
    login_user,
    logout_user,
    login_required,
    current_user,
)
from flask_argon2 import Argon2
from flask_wtf import FlaskForm
from wtforms import StringField, PasswordField, SubmitField
from wtforms.validators import DataRequired, Length
import redis

logging.basicConfig(
    filename="budget_tracker.log",
    level=logging.INFO,
    format="%(asctime)s %(levelname)s %(message)s",
)

app = Flask(__name__)
app.config.update(
    SECRET_KEY=os.environ["SECRET_KEY"],              # do not hard-code
    WTF_CSRF_SECRET_KEY=os.environ["WTF_CSRF_SECRET_KEY"],
    WTF_CSRF_ENABLED=True,
    SQLALCHEMY_DATABASE_URI="sqlite:///budget_tracker.db",
    SQLALCHEMY_TRACK_MODIFICATIONS=False,
    SESSION_COOKIE_HTTPONLY=True,
    SESSION_COOKIE_SAMESITE="Lax",
    SESSION_COOKIE_SECURE=True,                        # requires HTTPS
    REMEMBER_COOKIE_HTTPONLY=True,
    REMEMBER_COOKIE_SECURE=True,
    ARGON2_TIME_COST=3,
    ARGON2_MEMORY_COST=65536,
    ARGON2_PARALLELISM=2,
)

db = SQLAlchemy(app)
argon2 = Argon2(app)

login_manager = LoginManager()
login_manager.init_app(app)
login_manager.login_view = "login"
login_manager.login_message_category = "warning"
login_manager.session_protection = "strong"

r = redis.Redis(host="localhost", port=6379, db=0, decode_responses=True)

MAX_ATTEMPTS = 5
LOCKOUT_SECONDS = 3600


class User(UserMixin, db.Model):
    __tablename__ = "users"

    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(50), unique=True, nullable=False, index=True)
    email = db.Column(db.String(255), unique=True, nullable=False)
    password_hash = db.Column(db.Text, nullable=False)


@login_manager.user_loader
def load_user(user_id):
    try:
        return db.session.get(User, int(user_id))
    except (TypeError, ValueError):
        return None


class LoginForm(FlaskForm):
    username = StringField(
        "Username",
        validators=[DataRequired(), Length(max=50)],
    )
    password = PasswordField(
        "Password",
        validators=[DataRequired(), Length(max=50)],
    )
    submit = SubmitField("Log in")


def is_locked_out(username):
    try:
        return r.exists(f"lockout:{username}") == 1
    except redis.RedisError:
        app.logger.exception("Redis error while checking lockout")
        return False


def record_failed_login(username):
    try:
        key = f"attempt:{username}"
        count = r.incr(key)
        if count == 1:
            r.expire(key, LOCKOUT_SECONDS)
        if count >= MAX_ATTEMPTS:
            r.setex(f"lockout:{username}", LOCKOUT_SECONDS, "1")
            r.delete(key)
    except redis.RedisError:
        app.logger.exception("Redis error while recording failed login")


def clear_failed_logins(username):
    try:
        r.delete(f"attempt:{username}", f"lockout:{username}")
    except redis.RedisError:
        app.logger.exception("Redis error while clearing failed logins")


def is_safe_redirect(target):
    ref_url = urlparse(request.host_url)
    test_url = urlparse(urljoin(request.host_url, target))
    return (
        test_url.scheme in ("http", "https")
        and ref_url.netloc == test_url.netloc
    )


@app.route("/login", methods=["GET", "POST"])
def login():
    if current_user.is_authenticated:
        return redirect(url_for("dashboard"))

    form = LoginForm()

    if form.validate_on_submit():
        username = form.username.data.strip()
        password = form.password.data

        if is_locked_out(username):
            flash("Too many failed attempts. Try again in one hour.", "danger")
            return render_template("login.html", form=form), 429

        user = User.query.filter_by(username=username).first()
        authenticated = False

        if user:
            try:
                # Verify against the STORED hash. Do not re-hash the submitted
                # password and compare it to a newly generated hash.
                authenticated = argon2.verify_password(
                    user.password_hash,
                    password,
                )
            except Exception:
                app.logger.exception("Argon2 verification failed")
                authenticated = False

        if authenticated:
            clear_failed_logins(username)
            login_user(user)
            app.logger.info("Login success username=%s", username)

            next_page = request.args.get("next")
            if next_page and is_safe_redirect(next_page):
                return redirect(next_page)
            return redirect(url_for("dashboard"))

        record_failed_login(username)
        app.logger.warning("Login failure username=%s", username)

        # Generic message: don't reveal whether the username exists.
        flash("Invalid username or password.", "danger")

    return render_template("login.html", form=form)


@app.route("/logout")
@login_required
def logout():
    logout_user()
    return redirect(url_for("login"))


@app.route("/dashboard")
@login_required
def dashboard():
    return render_template("dashboard.html")


# Example protected route: enforce ownership, not just login.
@app.route("/transactions/<int:transaction_id>")
@login_required
def transaction_detail(transaction_id):
    transaction = Transaction.query.get_or_404(transaction_id)
    if transaction.user_id != current_user.id:
        abort(403)
    return render_template("transaction_detail.html", transaction=transaction)
```

